final class DeploymentConfig {
    const FORMAT='davvag-bundle', VERSION='1.0', MAX_ARCHIVE=268435456, MAX_EXPANDED=536870912, MAX_FILES=20000, MAX_FILE=67108864;
    public $tenantRoot,$frameworkRoot,$appRoot,$storageRoot,$localPluginRoot,$globalPluginRoot;
    function __construct($tenantRoot,$appRoot=null,$storageRoot=null){
        $root=realpath($tenantRoot); if(!$root) throw new RuntimeException('Tenant root does not exist.');
        $this->tenantRoot=rtrim($root,'\\/'); $this->frameworkRoot=dirname(dirname($this->tenantRoot));
        $this->localPluginRoot=defined('PLUGIN_PATH_LOCAL')?rtrim((string)PLUGIN_PATH_LOCAL,'\\/'):$this->tenantRoot.'/plugins';
        $this->globalPluginRoot=defined('PLUGIN_PATH')?rtrim((string)PLUGIN_PATH,'\\/'):$this->frameworkRoot.'/plugins';
        $this->appRoot=$appRoot?:$this->tenantRoot.'/apps/davvag-developer'; $this->storageRoot=$storageRoot?:$this->appRoot.'/storage';
        foreach(array('','/artifacts','/uploads','/staging','/backups','/audit') as $dir) SafeFiles::mkdir($this->storageRoot.$dir);
    }
}

