final class ApplicationDiscovery {
    private $c; function __construct(DeploymentConfig $c){$this->c=$c;}
    static function validId($id){return is_string($id)&&preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/',$id);}
    static function packageable($rel){$rel=strtolower(str_replace('\\','/',$rel));return !preg_match('#(^|/)(storage|cache|logs?|tmp|\.git|\.svn|node_modules)(/|$)#',$rel)&&!preg_match('/(^|\/)(\.env($|\.)|config\.local\.|secrets?\.|credentials?\.)/i',$rel)&&!preg_match('/\.(log|tmp|bak|swp|pfx|p12|pem|key)$/i',$rel);}
