    function descriptor($id){if(!self::validId($id))throw new RuntimeException('Invalid application ID.');return SafeFiles::json($this->c->tenantRoot.'/apps/'.$id.'/app.json');}
    function discover(){
        $tenant=SafeFiles::json($this->c->tenantRoot.'/tenant.json');$registered=isset($tenant['apps'])&&is_array($tenant['apps'])?$tenant['apps']:array();$apps=array();
        foreach($registered as $id=>$registration){if(!self::validId($id)||!is_file($this->c->tenantRoot.'/apps/'.$id.'/app.json'))continue;try{$d=$this->descriptor($id);}catch(Throwable $e){continue;}$deps=$this->deps(isset($d['dependencies'])?$d['dependencies']:array());$stats=SafeFiles::stats($this->c->tenantRoot.'/apps/'.$id,array(__CLASS__,'packageable'));$schemas=array_filter($deps['schemas'],function($s){return is_file($this->c->tenantRoot.'/schemas/'.$s.'.json');});$flows=array_filter($deps['workflows'],function($f){return is_file($this->c->tenantRoot.'/davvag-flow/'.str_replace('/',DIRECTORY_SEPARATOR,$f));});$missing=array();foreach($deps['apps'] as $x)if(!isset($registered[$x]))$missing[]='app:'.$x;foreach($deps['schemas'] as $x)if(!in_array($x,$schemas,true))$missing[]='schema:'.$x;foreach($deps['workflows'] as $x)if(!in_array($x,$flows,true))$missing[]='workflow:'.$x;$pluginCount=0;foreach($deps['plugins']as$group)$pluginCount+=count($group);$desc=isset($d['description'])&&is_array($d['description'])?$d['description']:array();$apps[]=array('id'=>$id,'name'=>isset($desc['title'])?$desc['title']:$id,'version'=>isset($desc['version'])?(string)$desc['version']:null,'description'=>isset($desc['summary'])?$desc['summary']:(isset($desc['description'])?$desc['description']:''),'author'=>isset($desc['author'])?$desc['author']:null,'dependencies'=>$deps,'plugin_count'=>$pluginCount,'workflow_count'=>count($flows),'database_table_count'=>count($schemas),'estimated_bundle_size'=>$stats['bytes'],'estimated_file_count'=>$stats['files'],'compatibility_status'=>$missing?'missing-dependencies':'compatible','missing'=>$missing);}
